// ─── FNV-1a Hash Helpers ──────────────────────────────────────────────────────

/** FNV-1a offset basis for 64-bit hash */
const FNV_OFFSET: bigint = 0xcbf29ce484222325n;
/** FNV-1a prime for 64-bit hash */
const FNV_PRIME: bigint = 0x00000100000001B3n;
/** 64-bit mask */
const MASK_64: bigint = 0xFFFFFFFFFFFFFFFFn;

/**
 * Compute FNV-1a 64-bit hash of a string.
 * @param str - The input string.
 * @returns The 64-bit hash value as bigint.
 */
export function fnv1a_64(str: string): bigint {
    let h: bigint = FNV_OFFSET;
    const encoder = new TextEncoder();
    const bytes = encoder.encode(str);
    for (const b of bytes) {
        h = (h ^ BigInt(b)) * FNV_PRIME;
        h = h & MASK_64;
    }
    return h;
}

/**
 * Compute the contract ID for "name@major_version" using FNV-1a 64-bit.
 * @param name - The contract name.
 * @param majorVersion - The major version.
 * @returns The contract ID as bigint.
 */
export function contractId(name: string, majorVersion: number): bigint {
    return fnv1a_64(`${name}@${majorVersion}`);
}

/**
 * Compute an extension ID from its name using FNV-1a lower 32 bits.
 * @param name - The extension name.
 * @returns The extension ID as number (uint32).
 */
export function extensionId(name: string): number {
    const h: bigint = fnv1a_64(name);
    return Number(h & 0xFFFFFFFFn);
}

/**
 * Compute a bundle ID from its name using FNV-1a 64-bit hash.
 * @param name - The bundle name.
 * @returns The bundle ID as bigint.
 */
export function bundleId(name: string): bigint {
    return fnv1a_64(name);
}

/**
 * Calculate host contract ID from name and major version.
 * @param name - The host contract name.
 * @param major - The major version.
 * @returns The host contract ID as bigint.
 */
export function hostContractId(name: string, major: number): bigint {
    return fnv1a_64(`host_contract:${name}@${major}`);
}

/**
 * Calculate plugin contract ID from name and major version.
 * @param name - The plugin contract name.
 * @param major - The major version.
 * @returns The plugin contract ID as bigint.
 */
export function pluginContractId(name: string, major: number): bigint {
    return fnv1a_64(`plugin_contract:${name}@${major}`);
}

// ─── String Helpers ────────────────────────────────────────────────────────────

/**
 * Convert a StringView to a JavaScript string.
 * @param sv - The StringView to convert.
 * @returns The JavaScript string, or empty string if null/empty.
 */
export function stringViewToString(sv: StringView | null | undefined): string {
    if (!sv || sv.ptr === 0n || sv.len === 0) return '';
    // Note: Actual implementation requires FFI access to read memory.
    // This is a placeholder - the host/guest libraries provide actual implementation.
    return '';
}

/**
 * Strip a prefix from a string.
 * @param sv - The input StringView or string.
 * @param prefix - The prefix to strip.
 * @returns The string without prefix, or original if prefix not present.
 */
export function stripPrefix(sv: StringView | string, prefix: string): string {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    if (s.startsWith(prefix)) {
        return s.slice(prefix.length);
    }
    return s;
}

/**
 * Check if a string starts with a prefix.
 * @param sv - The input StringView or string.
 * @param prefix - The prefix to check.
 * @returns True if the string starts with the prefix.
 */
export function startsWith(sv: StringView | string, prefix: string): boolean {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    return s.startsWith(prefix);
}

/**
 * Split a string by a delimiter.
 * @param sv - The input StringView or string.
 * @param delimiter - The delimiter to split by.
 * @returns An array of strings.
 */
export function split(sv: StringView | string, delimiter: string): string[] {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    return s.split(delimiter);
}

